+	 * This matches the C lockdep_assert_once() in irqfd_is_active().
+	 */
+	lockdep_assert_once(lockdep_is_held(&kvm->irqfds.lock) ||
+			    srcu_read_lock_held(&kvm->irq_srcu));
+}
